// Presentation-only colors; recorded events, mechanics and replay payloads are unchanged.
const BATTLE_LOG_EVENT_TONES=Object.freeze(Object.fromEntries([
 ['attack','resolved_hit terrain_damage counter_bolt_release counter_bolt_end contact_retaliation haste_changed followup_marked followup_strike charge_impact charge_counter priority_strike bomb_explode death_explode chain_link projectile_release flight_projectile_end projectile_end orb_projectile_end moon_projectile_end moon_pierce_contact melee_action_start melee_action_end combo_melee_start combo_melee_contact combo_melee_end charged_shot_start charged_shot_end moon_action_start moon_action_end orb_action_start orb_action_end pillar_action_start pillar_release pillar_action_end corner_pillar_start corner_pillar_release corner_pillar_end guard_warning guard_contact high_action_start high_action_end shockwave_release high_breath_release high_cleave_swing wave4_action_start wave4_action_end ground_burst cleave_release breath_release golem_ground_contact'],
 ['support','heal slow_cleansed healing_pulse self_repair ration_given revive_start revive_complete revive_cancel exposure_cleansed'],
 ['defense','guard_intercept parry_block counter_barrier_block aegis_block ward_block ward_consumed ward_granted ward_group_granted defense_action_start defense_action_end counter_barrier_activated aegis_action_start aegis_activated aegis_target_acquired aegis_action_end stability_aura_activated knockback_resisted'],
 ['control','repulsion_push dispel_action_start buff_dispelled dispel_action_end slow_applied cadence_delayed poison_applied poison_cloud healing_block_applied trap_triggered trap_placed trap_armed trap_expired exposure_applied'],
 ['mobility','move_boost_applied move_pulse burrow_warning burrow_start burrow_emerge retreat_start'],
 ['summon','summon_spawn split_spawn slime_split book_action_start book_batch_committed book_action_end summon_expired'],
 ['neutral','status_expired unit_defeated battle_finished log_gap']
].flatMap(([tone,events])=>events.split(' ').map(type=>[type,tone]))));
const BATTLE_LOG_STATUS_TONES=Object.freeze({slowImmunity:'defense',poisonImmunity:'defense',cadenceImmunity:'defense',exposureImmunity:'defense',poison:'control',slow:'control',root:'control',exposure:'control',ward:'defense',moveBoost:'mobility',followup:'attack',healingBlock:'control',barrier:'defense',aegis:'defense',stability:'defense',burrow:'mobility',retreat:'mobility'});
function battleLogActionTone(row){
 const type=row?.type,data=row?.data||{};
 if(type==='status_expired')return Object.hasOwn(BATTLE_LOG_STATUS_TONES,data.status)?BATTLE_LOG_STATUS_TONES[data.status]:'neutral';
 if(type==='defense_action_start'||type==='defense_action_end')return data.kind==='repair'?'support':'defense';
 if(type==='wave4_action_start'||type==='wave4_action_end')return data.kind==='stability'?'defense':'attack';
 return Object.hasOwn(BATTLE_LOG_EVENT_TONES,type)?BATTLE_LOG_EVENT_TONES[type]:'neutral';
}
